import OpenAI from 'openai'

export async function onRequestPost(context) {
  try {
    const body = await context.request.json()

    const {
      type,
      language,
      style,
      description,
    } = body

    if (!type || !language || !style || !description?.trim()) {
      return new Response(
        JSON.stringify({
          error: 'Please provide all naming preferences.',
        }),
        {
          status: 400,
          headers: {
            'Content-Type': 'application/json',
          },
        },
      )
    }

    if (!context.env.OPENAI_API_KEY) {
      return new Response(
        JSON.stringify({
          error: 'OpenAI API key is not configured.',
        }),
        {
          status: 500,
          headers: {
            'Content-Type': 'application/json',
          },
        },
      )
    }

    const openai = new OpenAI({
      apiKey: context.env.OPENAI_API_KEY,
    })

    const response = await openai.responses.create({
      model: 'gpt-4.1-mini',

      instructions: `
You are the naming engine for MyNameLab.

Generate exactly 10 high-quality naming suggestions.

Rules:

1. Generate exactly 10 names.
2. Never generate duplicate names.
3. Respect the requested naming category.
4. Respect the requested language and cultural context.
5. Respect the requested style.
6. Use the user's description as the main creative brief.
7. Prefer real words, real names, established naming patterns,
   and natural combinations.
8. Never invent a false meaning.
9. Never invent a false cultural origin.
10. If the meaning or origin is uncertain, explicitly say:
    "Meaning/origin not confidently established."
11. If a name is invented, clearly label it as "Invented".
12. Avoid generic or lazy suggestions.
13. Make the 10 names meaningfully different from one another.
14. Keep explanations concise.
15. Do not include numbers, bullet points, markdown, or commentary
    outside the requested JSON structure.
      `,

      input: `
Naming category: ${type}

Language / cultural context: ${language}

Style: ${style}

User description:
${description}

Generate exactly 10 names.
      `,

      text: {
        format: {
          type: 'json_schema',
          name: 'mynamelab_names',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              names: {
                type: 'array',
                minItems: 10,
                maxItems: 10,
                items: {
                  type: 'object',
                  properties: {
                    name: {
                      type: 'string',
                    },
                    type: {
                      type: 'string',
                    },
                    meaning: {
                      type: 'string',
                    },
                    origin: {
                      type: 'string',
                    },
                    pronunciation: {
                      type: 'string',
                    },
                    explanation: {
                      type: 'string',
                    },
                    whyItWorks: {
                      type: 'string',
                    },
                  },
                  required: [
                    'name',
                    'type',
                    'meaning',
                    'origin',
                    'pronunciation',
                    'explanation',
                    'whyItWorks',
                  ],
                  additionalProperties: false,
                },
              },
            },
            required: ['names'],
            additionalProperties: false,
          },
        },
      },
    })

    const result = JSON.parse(response.output_text)

    return new Response(
      JSON.stringify({
        success: true,
        names: result.names,
      }),
      {
        status: 200,
        headers: {
          'Content-Type': 'application/json',
        },
      },
    )
  } catch (error) {
    console.error('MyNameLab generation error:', error)

    return new Response(
      JSON.stringify({
        error: 'Something went wrong while generating names.',
      }),
      {
        status: 500,
        headers: {
          'Content-Type': 'application/json',
        },
      },
    )
  }
}